        if(saved!=null)account=saved.getString("selected_calendar_account",account);
        LinearLayout calendarCard=card(content,"Google Kalender");calendarStatus=text("");accountLabel=text("");calendarFailure=text("");calendarFailure.setTextColor(0xff823b24);calendarFailure.setVisibility(android.view.View.GONE);calendarFailure.setAccessibilityLiveRegion(android.view.View.ACCESSIBILITY_LIVE_REGION_POLITE);
        withoutBusy=button("Kalender ohne Belegtzeiten verbinden",()->{busy.setChecked(false);beginCalendarSetup();});withoutBusy.setVisibility(android.view.View.GONE);
        text("Deine Einsätze erscheinen im eigenen Kalender „Haus & Garten – Einsätze“. App-Termine bleiben erhalten. Keine Kundeneinladungen.");
